#define hue(v)  ( .6 + .6 * cos( v + vec4(0,23,21,0)  ) )

void mainImage(out vec4 O, vec2 u) {
  vec2 R = iResolution.xy,
       U = ( u+u - R ) / R.y;
  float a =  .15*iTime + atan(U.y,U.x)*4./3.14159; // angles are now [0..2x4[ instead of [0..2Pi[
  O = vec4( cos( 24.*(length(U) - a)) );           // spiral with 24 spires
  O = min(.5+.5*O/fwidth(O), 1.) * hue(a);         // f/df creates AA bands
}
